output_text:
[
  {
    "id": "no_carts_in_single_file_aisles",
    "text": "Shopping carts must not be taken into single-file shelf aisles where shelves border both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          {
            "and": [
              "hasCart",
              "singleFileAisle"
            ]
          },
          "enterSingleFileWithCart"
        ]
      }
    }
  },
  {
    "id": "park_before_narrow_item_aisle",
    "text": "At the mouth of a single-file item aisle, a shopper with a cart must not go north into the aisle without first parking the cart.",
    "abstraction": {
      "state_properties": {
        "pickupAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "wideMouthArea": {
          "and": [
            "pickupAisleMouth",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        }
      },
      "events": {
        "cartParkedAtMouth": {
          "pre": {
            "and": [
              "wideMouthArea",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "pickupAisleMouth",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "cart_parking_only_at_aisle_mouths",
    "text": "A shopper may park or detach from the cart only at designated wide staging mouths for narrow aisles.",
    "abstraction": {
      "state_properties": {
        "pickupAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "designatedCartStaging": {
          "and": [
            "pickupAisleMouth",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            }
          ]
        }
      },
      "events": {
        "cartParked": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartParked",
          {
            "not": "designatedCartStaging"
          }
        ]
      }
    }
  },
  {
    "id": "recover_parked_cart",
    "text": "Whenever a shopper parks a cart to enter a narrow aisle, they are obliged to recover the cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "pickupAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartParkedAtMouth": {
          "pre": {
            "and": [
              "pickupAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartRetrievedAtMouth": {
          "pre": {
            "and": [
              "pickupAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartParkedAtMouth",
      "discharge": "cartRetrievedAtMouth"
    }
  },
  {
    "id": "no_cartless_open_floor_travel",
    "text": "Except in the entrance cart area or when stepping into a single-file shelf aisle, shoppers should not move around open aisles without their cart.",
    "abstraction": {
      "state_properties": {
        "cartPickupArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "singleFileAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithoutCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openAisle",
          {
            "not": "hasCart"
          },
          {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          },
          {
            "not": "cartPickupArea"
          },
          {
            "not": "enterSingleFileWithoutCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_non_singlefile_shelf_service",
    "text": "Shelf interactions away from single-file aisles should be performed with the cart present.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "ordinaryShelfAccess": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {
        "shelfInteractionWithoutCart": {
          "pre": {
            "and": [
              "ordinaryShelfAccess",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "shelfInteractionWithoutCart"
    }
  },
  {
    "id": "no_cart_service_in_side_pinch_points",
    "text": "A shopper with a cart should not stop to take items from a shelf while standing in a narrow side pinch point.",
    "abstraction": {
      "state_properties": {
        "sidePinchPoint": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                2
              ]
            }
          ]
        },
        "cartSideShelfServicePoint": {
          "and": [
            "sidePinchPoint",
            "hasCart",
            "adjShelf"
          ]
        }
      },
      "events": {
        "cartShelfServiceInSidePinch": {
          "pre": {
            "and": [
              "cartSideShelfServicePoint",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartShelfServiceInSidePinch"
    }
  },
  {
    "id": "avoid_horizontal_cart_flow_in_two_wide_gaps",
    "text": "Carts should not be driven horizontally through two-wide shelf-side gaps, to avoid blocking the narrow side aisle.",
    "abstraction": {
      "state_properties": {
        "twoWideSideGap": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                2
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "horizontalCartMoveInSideGap": {
          "pre": {
            "and": [
              "hasCart",
              "twoWideSideGap",
              {
                "or": [
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "horizontalCartMoveInSideGap"
    }
  }
]
